int mon(int m,int n)
{
	switch (m)
	{
	case 1:
	case 3:
	case 5:
	case 7:
	case 8:
	case 10:
		return 31;
	case 4:
	case 6:
	case 9:
	case 11:
		return 30;
	default:
		if (run(n))
			return 29;
		else
			return 28;
	}
}


